parts.text:
[
  {
    "statement": "In southeast Australian estuaries, both short and long flexible habitats on subtidal artificial structures showed mixed effects on fish and invertebrate populations.",
    "citations": []
  },
  {
    "statement": "The outcomes of adding flexible habitats to subtidal artificial structures varied by species, survey timing, and habitat characteristics.",
    "citations": []
  },
  {
    "statement": "Long flexible habitats supported macroalgae and non-mobile invertebrate or fish species that were absent from structure surfaces without these habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The effect of long flexible habitats on fish species richness around structures depended on which fish were present when the flexible habitats were created.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats had mixed effects on the abundance of fishes or seahorses, with outcomes depending on the species and timing.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "For invertebrates, long flexible habitats had mixed effects on mobile and non-mobile invertebrate abundance, depending on the species group and survey week.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "One study reported that flexible habitats decreased mussel abundance on structure surfaces, but the flexible habitats themselves supported a higher biomass than the structure surfaces.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Short flexible habitats had mixed effects on mobile and non-mobile invertebrate community composition, with effects depending on the density or length of the flexible habitats.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Short flexible habitats had mixed effects on mobile and non-mobile invertebrate abundance, depending on the survey week, species group, and flexible habitat length.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Short flexible habitats had mixed effects on seahorse abundance, depending on the survey week.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Seahorses used long flexible habitats.",
    "citations": [
      "3451",
      "3450"
    ]
  },
  {
    "statement": "Behavioral data was not available for the use of short flexible habitats by seahorses.",
    "citations": [
      "3451",
      "3450"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions (>50 mm) on subtidal artificial structures on biodiversity.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "No evidence exists to indicate whether or not creating large protrusions (>50 mm) on subtidal artificial structures has any desirable or harmful effects.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "Creating grooves and small protrusions, ridges or ledges (1-50 mm) was examined in three studies from marinas in northern Israel and the UK, and on an open coastline in southeast Spain.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Smaller-scale modifications (1-50 mm) on subtidal artificial structures showed mixed effects on biodiversity.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Some studies on smaller-scale modifications (1-50 mm) found altered community composition and increased species richness and diversity.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Other studies on smaller-scale modifications (1-50 mm) found no increase in species diversity but mixed effects on species richness depending on surface orientation.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Creating small protrusions (1-50 mm) alone was examined in one study in Japan.",
    "citations": [
      "3453"
    ]
  },
  {
    "statement": "A study in Japan on creating small protrusions (1-50 mm) reported mixed effects on macroalgal abundance depending on the species.",
    "citations": [
      "3453"
    ]
  },
  {
    "statement": "Textured surfaces (≤1 mm) were examined in three studies from Italy, Israel, and the USA.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Studies on textured surfaces (≤1 mm) showed variable effects on community composition, richness, and abundance.",
    "citations": [
      "3449"
    ]
  }
]

[
  {
    "statement": "Ten studies examined the effects of transplanting or seeding species onto intertidal artificial structures.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Seven of these studies were conducted in estuaries in southeast Australia and Hong Kong.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Three studies in Hong Kong and Australia reported that oysters transplanted onto intertidal artificial structures supported macroalgae, mobile invertebrate, non-mobile invertebrate and fish species.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The supported species were absent from structure surfaces that did not have transplanted oysters.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Three studies found that transplanting oysters had mixed effects on combined macroalgae and invertebrate species richness and/or diversity on structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The mixed effects on species richness and/or diversity depended on the site and/or the presence and size of grooves and small ridges or ledges on the surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study in Australia found that transplanting oysters increased mobile invertebrate species richness on structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Two of three studies in Australia found that transplanting oysters and/or coralline algae did not increase fish species richness on and around structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study found mixed effects of transplanting oysters and/or coralline algae on fish species richness, with the effects depending on surface features and site.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Two studies in Australia found mixed effects on combined macroalgae and invertebrate abundance, depending on surface features.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Two of three studies in Hong Kong and Australia found that transplanting oysters had mixed effects on mobile invertebrate abundance depending on surface features and/or site.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study found that transplanting oysters increased non-mobile invertebrate and oyster recruit abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The same study that found an increase in some invertebrates also found a decreased abundance of barnacles.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Two of three studies in Australia found that transplanting oysters and/or coralline algae did not increase fish abundance on and around structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Six of eight studies in Australia, Spain, Singapore and Hong Kong reported that the survival of transplanted mobile and non-mobile invertebrates varied depending on species, site, and/or the presence and size of surface features.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Higher oyster survival was reported when oysters were transplanted into grooves compared with on ridges.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study in Australia found that transplanting oysters and/or coralline algae did not increase the time fishes spent interacting with structure surfaces or the number of bites taken.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The same study found that benthic fishes took more bites from surfaces with transplanted oysters than from surfaces with transplanted algae and oysters together.",
    "citations": [
      "3472"
    ]
  }
]

[
  {
    "statement": "Several habitat creation methods are effective for increasing species richness and diversity on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Rock pools are among the most consistently effective methods for increasing combined macroalgae, invertebrate and/or fish species diversity and/or richness.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Rock pools supported species that were absent from structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Pit habitats of 1-50 mm showed strong effectiveness for increasing combined macroalgae and invertebrate species richness and/or diversity.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Pit habitats supported macroalgae, invertebrate and/or fish species that were absent from surfaces without added habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Hole habitats larger than 50 mm demonstrated consistent positive effects in increasing combined macroalgae and invertebrate species diversity and/or richness.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats supported species that were absent from structure surfaces without added habitat features.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Combinations of grooves and small ridges or ledges of 1-50 mm showed effectiveness in increasing combined macroalgae and invertebrate species diversity and/or richness.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Combinations of grooves and small ridges or ledges supported species that were absent from structure surfaces without these features.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Groove habitats of 1-50 mm, when used alone, showed mixed results for increasing species richness and/or diversity.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Grooves consistently supported species that were absent from structure surfaces without grooves.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Small protrusions of 1-50 mm, when combined with other habitat types, showed positive effects on increasing combined macroalgae and invertebrate species richness.",
    "citations": [
      "3462"
    ]
  },
  {
    "statement": "Small ridges or ledges of 1-50 mm, when used alone, showed limited effectiveness, with mixed results.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Small ridges or ledges typically supported lower species richness than the grooves created between them.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Large ridges or ledges greater than 50 mm showed inconsistent results for increasing species diversity.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Textured surfaces of 1 mm or less had mixed effects on species richness, depending on the type of texture and the site.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Short flexible habitats of 1-50 mm decreased combined species richness in one study.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Creating water-retaining features like rock pools, holes, and pits is most effective for enhancing species richness and diversity on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Creating three-dimensional complexity through combinations of habitat types is most effective for enhancing species richness and diversity on intertidal artificial structures.",
    "citations": []
  }
]

[
  {
    "statement": "In European marine environments, the outcomes of creating textured surfaces on intertidal structures vary considerably depending on the type of texture created, the specific site, and the species being measured.",
    "citations": []
  },
  {
    "statement": "Studies from the UK and Netherlands demonstrate that creating textured surfaces (≤1 mm) had mixed effects on combined macroalgae and invertebrate species richness on structure surfaces.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "The outcomes of creating textured surfaces on combined macroalgae and invertebrate species richness depended on both the type of texture created and the site.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Creating textured surfaces, along with using environmentally-sensitive material, had mixed effects on barnacle and mobile invertebrate abundances, depending on the site.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "One study found that creating textured surfaces increased barnacle abundance regardless of texture type.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Different surface textures supported different abundances of barnacles.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "According to two studies in the Netherlands, creating textured surfaces did not increase macroalgal abundance on structure surfaces.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on intertidal structures in the UK had mixed effects on barnacle and mobile invertebrate abundances depending on the site.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on intertidal structures in the UK did not increase combined macroalgae and invertebrate species richness.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Natural topography on intertidal structures was colonized by macroalgae and limpets.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Limpets used shaded grooves and water-retaining depressions on surfaces with natural topography.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Creating groove habitats (1-50 mm) on intertidal structures showed varied outcomes across European studies.",
    "citations": []
  },
  {
    "statement": "In the UK and Netherlands, creating groove habitats did not increase macroalgal abundance on structure surfaces according to two studies.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Three of four studies from Australia, the Netherlands and the UK found that creating groove habitats did not increase invertebrate, limpet or chiton abundances.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Groove habitats were reported to be used by mussels and periwinkles in Netherlands studies.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Creating pit habitats (1-50 mm) on intertidal structures showed variable outcomes in European environments.",
    "citations": []
  },
  {
    "statement": "Studies from the UK and Netherlands found that creating pit habitats did not increase macroalgal abundance on structure surfaces according to three of four studies.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "For invertebrates, studies in the Netherlands and UK found mixed results when creating pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Some studies in the Netherlands and UK showed no increase in invertebrate abundance in pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Other studies in the Netherlands and UK found mixed effects on barnacle and mobile invertebrate abundances in pit habitats, depending on site, species, animal size, and pit characteristics.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Combined modifications on intertidal structures involving grooves and small protrusions, ridges or ledges (1-50 mm) demonstrated varied outcomes depending on multiple factors.",
    "citations": []
  },
  {
    "statement": "UK studies found that combined surface modifications had mixed effects on mobile invertebrate, non-mobile invertebrate, limpet, mussel, juvenile oyster and barnacle abundances.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The outcomes of combined surface modifications depended on the depth or height of grooves and ridges, the presence of large ledges or water-retaining and light-shading covers, the shore level, and the site.",
    "citations": [
      "3474"
    ]
  }
]

[
  {
    "statement": "Several actions can enhance fish communities on subtidal artificial structures based on available evidence.",
    "citations": []
  },
  {
    "statement": "Creating structural habitat features shows promise for enhancing fish communities on subtidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Long flexible habitats over 50 mm supported fish species that were absent from structure surfaces without such flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats had mixed effects on fish abundance depending on the species and the presence of fish when the habitats were created.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Small adjoining cavities or 'swimthrough' habitats of 100 mm or less supported six fish species that were absent from structure surfaces without swimthroughs.",
    "citations": [
      "3436"
    ]
  },
  {
    "statement": "Small adjoining cavities or 'swimthrough' habitats had mixed effects on juvenile fish community composition and abundance, depending on the site and survey conditions.",
    "citations": [
      "3436"
    ]
  },
  {
    "statement": "Large adjoining cavities or 'swimthrough' habitats greater than 100 mm supported fish species that were absent from structure surfaces without swimthroughs.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Large adjoining cavities or 'swimthrough' habitats increased overall fish species richness and abundance.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "When large adjoining cavities or 'swimthrough' habitats were added, individual species responses varied.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Creating hole habitats over 50 mm, combined with features like grooves and pits, supported fish species that were absent from structure surfaces without these added features.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "The effects on fish abundance from adding hole habitats with grooves and pits were mixed, depending on the species group.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Groove habitats between 1 and 50 mm, when combined with holes, pits, and environmentally-sensitive material, supported fish species that were absent from similar structures without these added features.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "The addition of groove habitats combined with other features had mixed effects on fish abundances depending on the species group.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "Management approaches, such as harvesting restrictions, also show benefits for fish communities on artificial structures.",
    "citations": []
  },
  {
    "statement": "Harvesting restrictions supported fish species that were absent from unrestricted structures and led to higher fish species richness.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "The effects of harvesting restrictions on total fish abundance were mixed.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "Reducing maintenance activities on artificial structures can increase seahorse abundance on the structure surfaces.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "Using environmentally-sensitive materials like ECOncrete™ combined with habitat features supported fish species that were absent from standard-concrete or fibreglass structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The effects of using environmentally-sensitive materials on fish abundances were mixed, depending on the species group.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Creating artificial reefs with different 3-D structures and materials showed no consistent differences in combined mobile invertebrate and fish richness or abundance between different reef designs.",
    "citations": [
      "2259"
    ]
  }
]

[
  {
    "statement": "Hole habitats and pit habitats on intertidal artificial structures both show positive effects on biodiversity.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "The effects of hole and pit habitats on biodiversity have been studied at different scales and have produced different outcomes.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "Hole habitats were examined in five studies.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Pit habitats were examined in twenty-two studies.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "More extensive research has been conducted on pit habitats than on hole habitats.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "Both hole and pit habitats altered the community composition of macroalgae and invertebrates on structure surfaces.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "Hole habitats supported species that were absent from unenhanced surfaces.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Four of six studies found that pit habitats altered community composition.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Pit habitats supported fish species that were absent from surfaces without added habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Three studies showed that hole habitats increased the combined diversity and/or richness of macroalgae and invertebrate species.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Pit habitats showed more variable results for species richness and diversity.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Eight of twelve studies found that pit habitats increased species richness and/or diversity.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Two studies found no increase in species richness and/or diversity from pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Two studies found pit habitats had mixed effects on species richness and/or diversity depending on the site.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "In separate studies, pit habitats increased the species richness of macroalgae, invertebrates, and fish.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "One study showed that hole habitats caused no increase in macroalgal abundance.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Two studies showed that hole habitats had mixed or no effects on invertebrate abundance.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Pit habitats showed variable effects on the abundance of organisms.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Two of five studies found that pit habitats increased the combined abundance of macroalgae and invertebrates.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Three of four studies found no increase in macroalgal abundance in pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Three of eight studies found no increase in invertebrate abundance in pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Fish abundance was increased by pit habitats in one study.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Both hole and pit habitats demonstrated actual use by organisms.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "Hole habitats were used by sea slugs, urchins, and octopuses.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Pit habitats were used by periwinkles, macroalgae, and invertebrates.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "The occupancy of pit habitats varied by the pit's size, its arrangement, and the species.",
    "citations": [
      "3475"
    ]
  }
]

[
  {
    "statement": "Outcomes from using environmentally-sensitive materials on subtidal artificial structures in Israel, the UK, and Australia vary significantly by location and material type.",
    "citations": []
  },
  {
    "statement": "In Israel, using ECOncrete™ in place of standard concrete, along with creating texture, grooves, holes, pits and small ledges, altered the combined macroalgae and invertebrate community composition.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In Israel, using ECOncrete™ in place of standard concrete with added texture increased species diversity on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The use of ECOncrete™ in Israel supported mobile invertebrate, non-mobile invertebrate and fish species that were absent from standard concrete surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The effects of using ECOncrete™ on fish abundances in Israel were mixed depending on the species group.",
    "citations": [
      "3455",
      "3434",
      "3448"
    ]
  },
  {
    "statement": "In the UK, studies found that using recycled-cement-concrete in place of standard-concrete altered the community composition of native species but not non-native species.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In the UK, using recycled-cement-concrete in place of standard-concrete did not increase diatom species richness on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In Australia, studies found that using quarried rock or shell-concrete in place of standard-concrete had mixed effects on community composition and species richness depending on the site and surface orientation.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Some Australian studies showed no increase in macroalgae and invertebrate abundance when using quarried rock or shell-concrete.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Other Australian studies found that using quarried rock or shell-concrete altered community composition.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Australian studies on long flexible habitats showed mixed effects on fish and invertebrate abundance depending on species groups, survey timing, and habitat characteristics.",
    "citations": [
      "3451"
    ]
  }
]

[
  {
    "statement": "The evidence for managing human activities on intertidal artificial structures is extremely limited.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects on biodiversity of ceasing or altering maintenance activities on intertidal artificial structures.",
    "citations": [
      "3440"
    ]
  },
  {
    "statement": "Only two studies have examined the effects of managing or restricting the harvesting of species on intertidal artificial structures.",
    "citations": [
      "3458"
    ]
  },
  {
    "statement": "The two studies examining harvesting management were conducted in Italy, Gibraltar and southeast Spain.",
    "citations": [
      "3458"
    ]
  },
  {
    "statement": "Studies found that restricting human access on intertidal artificial structures did not increase limpet abundance on structure surfaces.",
    "citations": [
      "3458"
    ]
  },
